import{d as g,C as e,o as h,c as d,j as a,a as i,E as o,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"中庸·第21章","description":"《中庸》第 21 章——自诚明谓之性，自明诚谓之教：诚则明矣，明则诚矣。天道与人道的两条进路。","frontmatter":{"title":"中庸·第21章","description":"《中庸》第 21 章——自诚明谓之性，自明诚谓之教：诚则明矣，明则诚矣。天道与人道的两条进路。","category":"guide","aliases":["第21章","中庸第21章","自诚明"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-21.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-21.md","lastUpdated":1790316338000}'),u={name:"lizhimingde/sishu-wujing/zhongyong/chapter-21.md"},x=g({...u,setup(p){const t=[{id:"chengming",label:"自诚明谓之性 · 自明诚谓之教",showLabel:!0,sentences:[["自",{text:"诚明",glossary:"chengming"},"，谓之",{text:"性",glossary:"xing"},"；自",{text:"明诚",glossary:"mingcheng"},"，谓之",{text:"教",glossary:"jiao"},"。"]],note:"「自诚明，谓之性」——由诚而明（先有其实，自然明照），这是「性」，即圣人天生之德；「自明诚，谓之教」——由明而诚（先明其理，再做到诚），这是「教」，即学者修习之路。一句分说「性」「教」两路。"},{id:"xiangtong",label:"诚则明矣 · 明则诚矣",showLabel:!0,sentences:[["诚则明矣，明则诚矣。"]],note:"「诚则明矣，明则诚矣」——诚了自然明，明了自然诚。二句合说：性、教虽分两途，其归则一。"}],r=[{id:"zi",term:"自",pinyin:"zì",meaning:"由、从。"},{id:"chengming",term:"诚明",pinyin:"chéng míng",meaning:"由诚而明。朱注：「德无不实而明无不照者，圣人之德，所性而有者也，天道也。」"},{id:"mingcheng",term:"明诚",pinyin:"míng chéng",meaning:"由明而诚。朱注：「先明乎善，而后能实其善者，贤人之学，由教而入者也，人道也。」"},{id:"xing",term:"性",pinyin:"xìng",meaning:"此处指天性、本性而有，即天道一路。"},{id:"jiao",term:"教",pinyin:"jiào",meaning:"教化、由教而入，即人道一路。"}];return(c,n)=>{const s=e("DaoTextReading"),l=e("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=a("h1",{id:"中庸·第21章",tabindex:"-1"},[i("中庸·第21章 "),a("a",{class:"header-anchor",href:"#中庸·第21章","aria-label":'Permalink to "中庸·第21章"'},"​")],-1)),n[1]||(n[1]=a("h2",{id:"【原典层】原文",tabindex:"-1"},[i("【原典层】原文 "),a("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=a("p",null,[i("第二十一章只有三句，讲「诚」与「明」的"),a("strong",null,"两条进路"),i("：自诚明（性／天道）、自明诚（教／人道）；末句说两者相通。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),o(s,{colophon:"自诚明 · 自明诚 · 诚则明矣",tone:"ink",sections:t,glossary:r,"default-mode":"slips","aria-label":"中庸·第21章 原文"}),n[3]||(n[3]=a("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[i("【原典层】注音与字词 "),a("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),o(l,{items:[{term:"自诚明",pinyin:["zì","chéng","míng"],meaning:"由诚而明。朱注归之「圣人之德，所性而有者也，天道也」。"},{term:"自明诚",pinyin:["zì","míng","chéng"],meaning:"由明而诚。朱注归之「贤人之学，由教而入者也，人道也」。"},{term:"性",pinyin:["xìng"],meaning:"天性而有，属天道。"},{term:"教",pinyin:["jiào"],meaning:"由教化而入，属人道。一为本有，一为修得。"}]}),n[4]||(n[4]=m('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>自诚明谓之性 · 自明诚谓之教</strong>：由诚而明的，叫作性（天性）；由明而诚的，叫作教（教化）。</p><p><strong>诚则明矣 · 明则诚矣</strong>：诚，就无不明白了；明，也就可以达到诚了。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第二十一章是极短的一章，只有三句：<strong>自诚明——性；自明诚——教。诚则明矣，明则诚矣。</strong></p><p>它说的是「诚」与「明」的两种进入方式：一种从诚出发（先有真实无妄的德，自然照见一切），一种从明出发（先明白善，再落到真实）。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它给两条路各安其名</strong>：朱注说得清楚——「德无不实而明无不照者，圣人之德，所性而有者也，<strong>天道</strong>也」；「先明乎善，而后能实其善者，贤人之学，由教而入者也，<strong>人道</strong>也」。<strong>一条是天生，一条是学成。</strong></li><li><strong>它承接第 20 章的「诚者／诚之者」</strong>：第 20 章说「诚者，天之道也；诚之者，人之道也」，本章把这两条路分别叫作「性」与「教」。<strong>这是同一件事的另一种说法。</strong></li><li><strong>「诚则明矣，明则诚矣」是两条路的汇合点</strong>：无论从哪头进，最终是一件事——诚到极处自然明，明到极处自然诚。</li><li><strong>它与第 4 章遥相呼应</strong>：第 4 章说「由不明，故不行」，本章说「明则诚矣」——<strong>明，是行得通的先决条件</strong>。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>认清自己走哪条路</strong>：有人本性笃实（先诚后明），有人靠学而明白（先明后诚）——不必强求同一条路。</li><li><strong>「明则诚」的提醒</strong>：真明白之后，做得到才成为可能；不明白而硬求「诚」，多半落空。</li><li><strong>两条路的终点相同</strong>：诚与明互为因果，不必分高下。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>这一章只有三句话，说的是两条路：</p><p>一条从<strong>诚</strong>出发——人本来真实无妄，自然把事情看得明白，这是「性」，属天道。 一条从<strong>明</strong>出发——先把道理弄明白，再把自己落成那个样子，这是「教」，属人道。</p><p>最后一句是两路的合拢：<strong>诚，就没有不明白的；明白，就能做到诚。</strong></p><p>换句话说：不管你是天生实在的人，还是靠学习明白过来的人，终点是同一个地方。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「自诚明」（先诚后明）与「自明诚」（先明后诚）——我更像哪一路？</li><li>「明则诚矣」——有没有「我明白，但就是做不到」的事？为什么做不到？</li><li>两条路终点相同——这个说法让我安心，还是让我不安？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-20">中庸·第20章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-22">中庸·第22章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',23))])}}});export{f as __pageData,x as default};
